import{_ as s,C as e,o as i,c as l,j as a,a as d,G as r,a3 as c}from"./chunks/framework.Bvm_liKL.js";const C=JSON.parse('{"title":"Installation & Update Channels","description":"ICC-CE system requirements, differences between installer and portable versions, and the meaning of four update channels","frontmatter":{"title":"Installation & Update Channels","description":"ICC-CE system requirements, differences between installer and portable versions, and the meaning of four update channels"},"headers":[],"relativePath":"en/guide/installation.md","filePath":"en/guide/installation.md"}'),u={name:"en/guide/installation.md"};function h(p,t,g,m,b,f){const o=e("ArticleMetadata"),n=e("UnderConstruction");return i(),l("div",null,[t[0]||(t[0]=a("h1",{id:"installation-update-channels",tabindex:"-1"},[d("Installation & Update Channels "),a("a",{class:"header-anchor",href:"#installation-update-channels","aria-label":'Permalink to "Installation & Update Channels"'},"​")],-1)),r(o),r(n),t[1]||(t[1]=c('<h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h2><p>Before you begin, please ensure your device meets the following requirements:</p><table tabindex="0"><thead><tr><th>Item</th><th>Requirement</th></tr></thead><tbody><tr><td><strong>Operating System</strong></td><td>Windows 10 version 1809 (build 17763) or later, or Windows 11</td></tr><tr><td><strong>Runtime</strong></td><td>.NET 6 Desktop Runtime (x64 or x86)</td></tr><tr><td><strong>Memory</strong></td><td>4 GB or more recommended</td></tr><tr><td><strong>Graphics</strong></td><td>Direct3D 11 capable GPU for hardware-accelerated ink rendering</td></tr><tr><td><strong>Input Device</strong></td><td>Mouse works; touchscreen / digitizer / active stylus recommended for best experience</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">How to check your system version?</p><p>Press <kbd>Win</kbd> + <kbd>Pause</kbd> to open System Information, where you can check your Windows version and system type (64-bit / 32-bit).</p></div><div class="warning custom-block"><p class="custom-block-title">About .NET Runtime</p><p>ICC-CE runs on .NET 6, <strong>not</strong> .NET Framework. The installer will automatically prompt you to download the runtime when needed. If the portable version fails to start, it&#39;s most likely due to a missing .NET 6 Desktop Runtime — search for &quot;.NET Desktop Runtime 6.x&quot; on Microsoft&#39;s official site and install the appropriate architecture (x64 / x86).</p></div><h2 id="getting-the-installer" tabindex="-1">Getting the Installer <a class="header-anchor" href="#getting-the-installer" aria-label="Permalink to &quot;Getting the Installer&quot;">​</a></h2><p>Visit the <a href="/website/en/download">Download Center</a> to choose your preferred version. The page will automatically select the optimal download route.</p><h3 id="the-four-update-channels" tabindex="-1">The Four Update Channels <a class="header-anchor" href="#the-four-update-channels" aria-label="Permalink to &quot;The Four Update Channels&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Channel</th><th>Description</th><th>Use Case</th></tr></thead><tbody><tr><td><strong>Beta (Recommended)</strong></td><td>Fastest updates, most timely fixes, passes CI auto-build and basic verification</td><td>Best for daily use</td></tr><tr><td><strong>Preview</strong></td><td>Pre-release builds without pre-release tags, more stable than Beta</td><td>For those who want early access with more stability</td></tr><tr><td><strong>Release</strong></td><td>Lowest release frequency, fully tested</td><td>For production environments with high stability requirements</td></tr><tr><td><strong>Nightly</strong></td><td>Untested debug builds, built directly from the latest net6 branch code</td><td><strong>For testing only, never use in actual classrooms</strong></td></tr></tbody></table><blockquote><p>Nightly builds require reading a risk disclaimer and checking a confirmation box before downloading. Updating to the next Nightly version requires manual download and replacement; auto-update is not supported.</p></blockquote><h2 id="installer-vs-portable" tabindex="-1">Installer vs Portable <a class="header-anchor" href="#installer-vs-portable" aria-label="Permalink to &quot;Installer vs Portable&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Comparison</th><th>Installer (.exe)</th><th>Portable (.zip)</th></tr></thead><tbody><tr><td>Installation</td><td>Run the setup wizard, completes automatically</td><td>Extract to any directory</td></tr><tr><td>Shortcuts</td><td>Automatically creates Start Menu and desktop shortcuts</td><td>Must be created manually</td></tr><tr><td>System Impact</td><td>Writes to installation directory and registry uninstall entry</td><td>No system writes at all</td></tr><tr><td>Uninstallation</td><td>Settings → Apps → Installed apps → Uninstall</td><td>Delete the folder directly</td></tr><tr><td>Use Case</td><td>Personal computers, classroom all-in-ones for long-term use</td><td>USB flash drives, batch deployment in computer labs, multiple versions</td></tr></tbody></table><h2 id="_32-bit-or-64-bit" tabindex="-1">32-bit or 64-bit? <a class="header-anchor" href="#_32-bit-or-64-bit" aria-label="Permalink to &quot;32-bit or 64-bit?&quot;">​</a></h2><ul><li>Modern devices should always choose <strong>64-bit (x64)</strong></li><li>Only choose <strong>32-bit (x86)</strong> if your system is 32-bit, or if you need deep integration with 32-bit Office</li></ul><h2 id="directory-structure-after-installation" tabindex="-1">Directory Structure After Installation <a class="header-anchor" href="#directory-structure-after-installation" aria-label="Permalink to &quot;Directory Structure After Installation&quot;">​</a></h2><p>After installation, the main program and data directories are located at:</p><ul><li><strong>Installer</strong>: <code>C:\\Program Files\\InkCanvasForClass CE\\</code> (or custom installation directory)</li><li><strong>Portable</strong>: The directory you extracted to</li></ul><p>User configuration and ink data are stored at:</p><ul><li><strong>Configuration</strong>: <code>%AppData%\\InkCanvasForClass CE\\Configs\\Settings.json</code></li><li><strong>Auto-saved ink</strong>: <code>%AppData%\\InkCanvasForClass CE\\Saves\\</code></li><li><strong>Screenshots</strong>: <code>%USERPROFILE%\\Pictures\\Ink Canvas Screenshots\\</code></li><li><strong>Log files</strong>: <code>%AppData%\\InkCanvasForClass CE\\Logs\\</code></li></ul><h2 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h2><p>ICC-CE has a built-in online update checker. For manual upgrades:</p><ul><li><strong>Installer</strong>: Run the new version installer to overwrite the existing installation; configuration and ink data are preserved</li><li><strong>Portable</strong>: Extract the new version over the old program directory to overwrite</li></ul><div class="warning custom-block"><p class="custom-block-title">Cross-channel Switching</p><p>When downgrading from Beta to Release, configuration entries written by the newer version may not be recognized by the older version. If issues occur, back up and delete the configuration file to let the program regenerate it.</p></div>',23))])}const v=s(u,[["render",h]]);export{C as __pageData,v as default};
